package org.xingmu.tv;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import android.view.*;import android.text.*;import java.util.*;import java.util.concurrent.*;
/** TVBox-style details, selectable playback lines, episode grid and resume. */
public final class EpisodeActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private LinearLayout root,body;private TextView status;private int generation;private VodApi.Movie movie;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout shell=TvUi.root(this);ScrollView scroll=new ScrollView(this);root=TvUi.col(this);scroll.addView(root);shell.addView(scroll,new LinearLayout.LayoutParams(-1,-1));LinearLayout bar=TvUi.row(this);bar.addView(TvUi.title(this,"影片详情",23),new LinearLayout.LayoutParams(0,-2,1));Button back=TvUi.button(this,"返回片库");back.setOnClickListener(v->finish());bar.addView(back);root.addView(bar);TvUi.gap(this,root,20);status=TvUi.text(this,"正在加载详情…",15,TvUi.MUTED);root.addView(status);body=TvUi.col(this);root.addView(body);load();}
 private void load(){String api=getIntent().getStringExtra("api"),id=getIntent().getStringExtra("movie");worker.execute(()->{try{VodApi.Movie chosen=VodCache.get(api,id);if(chosen==null){for(VodApi.Movie m:VodApi.parse(PublicHttp.get(VodApi.query(api,"ids",id))))if(m.id.equals(id)){chosen=m;VodCache.put(api,m);break;}}if(chosen==null)throw new java.io.IOException("此源未返回影片详情");final VodApi.Movie detail=chosen;runOnUiThread(()->{if(isDestroyed())return;movie=detail;details();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;status.setText("加载失败："+e.getMessage());Button retry=TvUi.button(this,"重新加载");body.addView(retry);retry.setOnClickListener(v->{body.removeAllViews();load();});});}});}
 private void details(){body.removeAllViews();LinearLayout hero=TvUi.row(this);FrameLayout cover=new FrameLayout(this);cover.setBackground(TvUi.gradient(0xff243e31,0xff172431,14));cover.setClipToOutline(true);cover.addView(new CinemaArt(this,1,TvUi.ACCENT,false),new FrameLayout.LayoutParams(-1,-1));ImageView poster=new ImageView(this);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.addView(poster,new FrameLayout.LayoutParams(-1,-1));PosterImage.load(poster,movie.poster);hero.addView(cover,new LinearLayout.LayoutParams(TvUi.dp(this,TvUi.wide(this)?140:100),TvUi.dp(this,TvUi.wide(this)?200:150)));LinearLayout info=TvUi.col(this);info.setPadding(TvUi.dp(this,20),0,0,0);info.addView(TvUi.title(this,movie.title,TvUi.wide(this)?30:23));TvUi.gap(this,info,12);info.addView(TvUi.text(this,FilmCategory.of(movie.category)+" · "+movie.category+" · "+movie.year,14,TvUi.MUTED));TvUi.gap(this,info,8);info.addView(TvUi.text(this,(movie.area.isEmpty()?"地区未提供":movie.area)+" · "+getIntent().getStringExtra("source"),13,TvUi.MUTED));if(!movie.actor.isEmpty()){TvUi.gap(this,info,10);TextView actor=TvUi.text(this,"主演："+movie.actor,13,TvUi.MUTED);actor.setMaxLines(2);info.addView(actor);}hero.addView(info,new LinearLayout.LayoutParams(0,-2,1));body.addView(hero);if(!movie.summary.isEmpty()){TvUi.gap(this,body,18);TextView description=TvUi.text(this,Html.fromHtml(movie.summary).toString().trim(),14,TvUi.MUTED);description.setMaxLines(4);body.addView(description);}TvUi.gap(this,body,22);body.addView(TvUi.title(this,"播放线路",20));String[] groups=movie.play.split("\\$\\$\\$");ArrayList<String> names=new ArrayList<>();names.add("自动 · 含备用线路");for(int n=0;n<groups.length;n++)names.add("线路 "+(n+1));Spinner lines=new Spinner(this);lines.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));body.addView(lines);LinearLayout episodes=TvUi.col(this);body.addView(episodes);lines.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){if(v instanceof TextView)((TextView)v).setTextColor(TvUi.INK);VodApi.Movie selected=n==0?movie:new VodApi.Movie(movie.id,movie.title,movie.category,movie.year,groups[n-1]);populate(selected,episodes);}});}
 private void populate(VodApi.Movie selected,LinearLayout panel){int token=++generation;panel.removeAllViews();status.setText("正在准备选集…");worker.execute(()->{try{String json=VodApi.episodes(selected,getIntent().getStringExtra("site"),getIntent().getStringExtra("source"));List<CatalogItem> entries=CatalogParser.parse(json);new CatalogRepository(this).merge(json,"films","未分类");runOnUiThread(()->{if(isDestroyed()||generation!=token)return;panel.removeAllViews();status.setText(entries.size()+" 集 · 可切换线路");ArrayList<String> ids=new ArrayList<>();for(CatalogItem item:entries)ids.add(item.id);int resume=0;for(String watched:new WatchStore(this).history()){int pos=ids.indexOf(watched);if(pos>=0){resume=pos;break;}}final int index=resume;Button play=TvUi.button(this,"▷  播放 / 继续观看");play.setTextColor(TvUi.ACCENT);panel.addView(play);LinearLayout tools=TvUi.row(this);Button download=TvUi.button(this,"下载选集"),center=TvUi.button(this,"下载中心");tools.addView(download,new LinearLayout.LayoutParams(0,-2,1));tools.addView(center,new LinearLayout.LayoutParams(0,-2,1));panel.addView(tools);center.setOnClickListener(v->startActivity(new Intent(this,DownloadsActivity.class)));download.setOnClickListener(v->{String[] names=new String[entries.size()];for(int n=0;n<entries.size();n++)names[n]=entries.get(n).title;new AlertDialog.Builder(this).setTitle("选择要下载的内容").setItems(names,(d,n)->OfflineStore.enqueue(this,entries.get(n))).setNegativeButton("取消",null).show();});play.setOnClickListener(v->play(ids,index));TvUi.gap(this,panel,18);panel.addView(TvUi.title(this,"选集",20));TvUi.gap(this,panel,10);GridLayout grid=new GridLayout(this);int columns=TvUi.wide(this)?6:getResources().getConfiguration().screenWidthDp>=600?4:3;grid.setColumnCount(columns);panel.addView(grid);for(int n=0;n<entries.size();n++){final int episode=n;String name=entries.get(n).title;String prefix=movie.title+" · ";if(name.startsWith(prefix))name=name.substring(prefix.length());Button button=TvUi.button(this,name);button.setTextSize(13);button.setMaxLines(2);GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(n/columns),GridLayout.spec(n%columns,1,1f));p.width=0;p.height=TvUi.dp(this,54);p.bottomMargin=8;if(n%columns>0)p.leftMargin=8;grid.addView(button,p);button.setOnClickListener(v->play(ids,episode));}});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()&&generation==token)status.setText("此线路不可用："+e.getMessage()+"。请更换线路。");});}});}
 private void play(ArrayList<String> ids,int index){startActivity(new Intent(this,PlayerActivity.class).putStringArrayListExtra("ids",ids).putExtra("index",index));}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}
}
